// helpers
func toString(v interface{}) string {
	if v == nil {
		return ""
	}
	switch s := v.(type) {
	case string:
		return s
	case []byte:
		return string(s)
	case fmt.Stringer:
		return s.String()
	default:
		return fmt.Sprintf("%v", v)
	}
}
func toInt64(v interface{}) (int64, error) {
	switch n := v.(type) {
	case int:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int64:
		return n, nil
	case uint:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case string:
		// try parse as int, including hex etc
		s := strings.TrimSpace(n)
		s = strings.ReplaceAll(s, ",", "")
		// handle 0x
		if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
			if v, err := strconv.ParseInt(s, 0, 64); err == nil {
				return v, nil
			}
		}
		if strings.Contains(s, ".") || strings.Contains(s, "e") || strings.Contains(s, "E") {
			f, err := strconv.ParseFloat(s, 64)
			if err != nil {
				return 0, err
			}
			return int64(f), nil
		}
		return strconv.ParseInt(s, 0, 64)
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	default:
		return 0, fmt.Errorf("cannot convert %T to int64", v)
	}
}
func toFloat64(v interface{}) (float64, error) {
	switch n := v.(type) {
	case int:
		return float64(n), nil
	case int8:
		return float64(n), nil
	case int16:
		return float64(n), nil
	case int32:
		return float64(n), nil
	case int64:
		return float64(n), nil
	case uint:
		return float64(n), nil
	case uint8:
		return float64(n), nil
	case uint16:
		return float64(n), nil
	case uint32:
		return float64(n), nil
	case uint64:
		return float64(n), nil
	case float32:
		return float64(n), nil
	case float64:
		return n, nil
	case string:
		s := strings.TrimSpace(n)
		s = strings.ReplaceAll(s, ",", "")
		return strconv.ParseFloat(s, 64)
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	default:
		return 0, fmt.Errorf("cannot convert %T to float64", v)
	}
}

// namespace structs
type Base64Funcs struct{}
func (b *Base64Funcs) Encode(in interface{}) string { return base64.StdEncoding.EncodeToString([]byte(toString(in))) }
func (b *Base64Funcs) Decode(in interface{}) (string, error) {
	s := toString(in)
	// try std then url
	if data, err := base64.StdEncoding.DecodeString(s); err == nil {
		return string(data), nil
	}
	if data, err := base64.URLEncoding.DecodeString(s); err == nil {
		return string(data), nil
	}
	if data, err := base64.RawStdEncoding.DecodeString(s); err == nil {
		return string(data), nil
	}
	return "", fmt.Errorf("illegal base64 data at input byte %d", 0)
}
func (b *Base64Funcs) DecodeBytes(in interface{}) ([]byte, error) {
	s := toString(in)
	if data, err := base64.StdEncoding.DecodeString(s); err == nil {
		return data, nil
	}
	if data, err := base64.URLEncoding.DecodeString(s); err == nil {
		return data, nil
	}
	return nil, fmt.Errorf("illegal base64")
}
type b64Funcs struct{}
func (b *b64Funcs) Encode(in interface{}) string { return (&Base64Funcs{}).Encode(in) }

type CollFuncs struct{}
func (c *CollFuncs) Dict(vals ...interface{}) map[string]interface{} {
	m := map[string]interface{}{}
	for i:=0; i<len(vals); i+=2 {
		key := toString(vals[i])
		var val interface{} = ""
		if i+1 < len(vals) {
			val = vals[i+1]
		}
		m[key]=val
	}
	return m
}
func (c *CollFuncs) Slice(vals ...interface{}) []interface{} { return vals }
func (c *CollFuncs) GoSlice(args ...interface{}) interface{} { return c.Slice(args...) }
func (c *CollFuncs) Has(in interface{}, item interface{}) bool {
	switch v := in.(type) {
	case []interface{}:
		for _, e := range v {
			if fmt.Sprintf("%v", e)==fmt.Sprintf("%v", item) { return true }
		}
		return false
	case map[string]interface{}:
		_, ok := v[toString(item)]
		return ok
	default:
		// try reflection?
		return false
	}
}
func (c *CollFuncs) Append(item interface{}, list interface{}) ([]interface{}, error) {
	switch v := list.(type) {
	case []interface{}:
		return append(v, item), nil
	default:
		return nil, fmt.Errorf("expected an array")
	}
}
func (c *CollFuncs) Prepend(item interface{}, list interface{}) ([]interface{}, error) {
	switch v := list.(type) {
	case []interface{}:
		return append([]interface{}{item}, v...), nil
	default:
		return nil, fmt.Errorf("expected an array")
	}
}
func (c *CollFuncs) Uniq(in interface{}) ([]interface{}, error) {
	switch v := in.(type) {
	case []interface{}:
		seen := map[string]bool{}
		var out []interface{}
		for _, e := range v {
