func (c *ConvFuncs) Default(def, in interface{}) interface{} {
	if in==nil { return def }
	switch v:=in.(type){
	case string:
		if v=="" { return def }
		return v
	case []interface{}:
		if len(v)==0 { return def }
		return v
	case map[string]interface{}:
		if len(v)==0 { return def }
		return v
	case bool:
		if !v { return def }
		return v
	case int, int64, float64:
		if fmt.Sprintf("%v",v)=="0" || fmt.Sprintf("%v",v)=="0.0" { return def }
		return v
	default:
		if fmt.Sprintf("%v",v)=="" || fmt.Sprintf("%v",v)=="<no value>" { return def }
		return v
	}
}
