func (s *StringFuncs) Indent(args ...interface{}) (string,error){
	// strings.Indent [width] [indent] input
	// can be called with 1,2,3 args
	var input string
	var width int =1
	var indentStr = " "
	if len(args)==1{
		input=toString(args[0])
	} else if len(args)==2{
		// could be width,input or indent,input? docs: strings.Indent [width] [indent] input
		// try to detect
		if w, err:=toInt64(args[0]); err==nil {
			width=int(w)
			input=toString(args[1])
		} else {
			indentStr=toString(args[0])
			input=toString(args[1])
		}
	} else if len(args)==3{
		w,_:=toInt64(args[0])
		width=int(w)
		indentStr=toString(args[1])
		input=toString(args[2])
	} else {
		return "",fmt.Errorf("wrong args")
	}
	if width<=0{ return "",fmt.Errorf("width must be >0")}
	if strings.Contains(indentStr, "\n"){ return "",fmt.Errorf("indent must not contain newline")}
	prefix:=strings.Repeat(indentStr, width)
	lines:=strings.Split(input, "\n")
	for i, l:=range lines{ lines[i]=prefix+l}
	return strings.Join(lines, "\n"),nil
}
func (s *StringFuncs) SkipLines(n int, in string) string {
	lines:=strings.Split(in, "\n")
