	switch v:=in.(type){
	case []interface{}:
		parts:=make([]string,len(v))
		for i,e:=range v{ parts[i]=s.ShellQuote(e)}
		return strings.Join(parts," ")
	default:
		str:=toString(in)
		// simple shell quote: wrap in single quotes, escape single quotes
		return "'" + strings.ReplaceAll(str, "'", "'\"'\"'") + "'"
	}
}
