// helpers for template exec
type TemplateInput struct {
	Name string
	Content string
	IsFile bool
	Path string
}

func gatherTemplates() ([]TemplateInput, error) {
	var inputs []TemplateInput
	if cli.InSet {
		inputs = append(inputs, TemplateInput{Name:"<arg>", Content: cli.In})
	} else if len(cli.InputFiles)>0 {
		for _, f := range cli.InputFiles {
			if f=="-" {
				data, err:=io.ReadAll(os.Stdin)
				if err!=nil{return nil,err}
				inputs = append(inputs, TemplateInput{Name:"-", Content:string(data)})
			} else {
				content, err:=os.ReadFile(f)
				if err!=nil{
					return nil, fmt.Errorf("fileToTemplate: stat %q: stat %s: %v", f, filepath.Base(f), err)
				}
				inputs = append(inputs, TemplateInput{Name:f, Content:string(content), IsFile:true, Path:f})
			}
		}
	} else if cli.InputDir != "" {
		// walk
		err:=filepath.Walk(cli.InputDir, func(path string, info os.FileInfo, err error) error{
			if err!=nil{return err}
			if info.IsDir(){return nil}
			rel, _:=filepath.Rel(cli.InputDir, path)
			// check include/exclude
			// exclude first
			matchedExclude:=false
			for _, pat:=range cli.Excludes{
				neg:=false
				if strings.HasPrefix(pat,"!"){
					pat=strings.TrimPrefix(pat,"!")
					neg=true
				}
				m, _:=filepath.Match(pat, rel)
				if m{
					if neg{
						matchedExclude=false
					} else {
						matchedExclude=true
					}
				}
				// also try base?
				m2,_:=filepath.Match(pat, filepath.Base(rel))
				if m2{
					if neg{matchedExclude=false}else{matchedExclude=true}
				}
			}
			if matchedExclude{return nil}
			if len(cli.Includes)>0{
				matched:=false
				for _, pat:=range cli.Includes{
					m,_:=filepath.Match(pat, rel)
					if m{matched=true;break}
					m2,_:=filepath.Match(pat, filepath.Base(rel))
					if m2{matched=true;break}
				}
				if !matched{return nil}
			}
			// check excludeProcessing: if matches, we will copy file directly later, not parse
			isExcludeProcessing:=false
			for _, pat:=range cli.ExcludeProcessing{
				m,_:=filepath.Match(pat, rel)
				if m{isExcludeProcessing=true;break}
				m2,_:=filepath.Match(pat, filepath.Base(rel))
				if m2{isExcludeProcessing=true;break}
			}
			content, err:=os.ReadFile(path)
			if err!=nil{return err}
			inputs = append(inputs, TemplateInput{Name:path, Content:string(content), IsFile:true, Path:path,})
			// store flag for excludeProcessing? We can handle later
			// For now mark via map
			if isExcludeProcessing{
				// we need to know later that this file should be copied not rendered
				// Add to a global map
				excludeProcessingPaths[path]=true
			}
			return nil
		})
		if err!=nil{return nil,err}
	} else {
		// default stdin
		data, err:=io.ReadAll(os.Stdin)
		if err!=nil{return nil,err}
		inputs = append(inputs, TemplateInput{Name:"-", Content:string(data)})
	}
	return inputs, nil
}

var excludeProcessingPaths = map[string]bool{}

func renderTemplates(inputs []TemplateInput, rootData map[string]interface{}) ([]string, []string, error) {
	// returns outputs and outputNames
	// need to prepare base template with funcMap and nested templates
	// First load additional templates via --template
	base := template.New("").Delims(cli.LeftDelim, cli.RightDelim)
	// missingKey option
	switch cli.MissingKey{
	case "error":
		base = base.Option("missingkey=error")
	case "zero":
		base = base.Option("missingkey=zero")
	default:
		base = base.Option("missingkey=invalid")
	}
	// create funcMap with base not yet fully? Need to create funcMap after base created (for tmpl funcs)
	fm := buildFuncMap(rootData, base)
	base.Funcs(fm)
	// also add built-in funcs like env, etc are already in fm

	// need to also add standard template funcs: and, or, not, etc are built-in, no need

	// load --template files
	for _, t := range cli.Templates {
		parts:=strings.SplitN(t,"=",2)
		if len(parts)!=2{continue}
		alias, path:=parts[0],parts[1]
		// if path ends with / then load all files in dir
		if strings.HasSuffix(path,"/") || strings.HasSuffix(path, string(os.PathSeparator)){
			entries, err:=os.ReadDir(path)
			if err!=nil{return nil,nil,err}
			for _, ent:=range entries{
				if ent.IsDir(){continue}
				full:=filepath.Join(path, ent.Name())
				data, err:=os.ReadFile(full)
				if err!=nil{return nil,nil,err}
				name:=alias+"/"+ent.Name()
				_, err=base.New(name).Parse(string(data))
				if err!=nil{return nil,nil,fmt.Errorf("parse template %s: %v", name, err)}
			}
		} else {
			data, err:=os.ReadFile(path)
			if err!=nil{return nil,nil,err}
			_, err=base.New(alias).Parse(string(data))
			if err!=nil{return nil,nil,fmt.Errorf("parse template %s: %v", alias, err)}
		}
	}

	var outputs []string
	var outNames []string

	for _, inp := range inputs {
		// handle excludeProcessing: copy without parsing
		if excludeProcessingPaths[inp.Path] {
			// will handle as copy later
			outputs = append(outputs, inp.Content)
			outNames = append(outNames, inp.Name)
			continue
		}
		// parse template
		tmplName := inp.Name
		tmpl, err:=base.New(tmplName).Parse(inp.Content)
		if err!=nil{
			return nil,nil,fmt.Errorf("parse template %s: %v", tmplName, err)
		}
		var buf bytes.Buffer
		ctx := rootData
		// If template name is file path, should execute with that template?
		// The base already has template, we use tmpl to execute
		err=tmpl.Execute(&buf, ctx)
		if err!=nil{
			return nil,nil,fmt.Errorf("failed to render template %s: %v", tmplName, err)
		}
		outputs = append(outputs, buf.String())
		outNames = append(outNames, tmplName)
	}
	return outputs, outNames, nil
}

func writeOutputs(outputs []string, outNames []string) error {
	// handle chmod
	var chmodMode os.FileMode
	chmodSet:=false
	if cli.Chmod != "" {
		v, err:=strconv.ParseUint(cli.Chmod,8,32)
		if err!=nil{
			return fmt.Errorf("strconv.ParseUint: parsing \"0%s\": invalid syntax", cli.Chmod)
		}
		chmodMode=os.FileMode(v)
		chmodSet=true
	}
	// cases
	if cli.InputDir != "" {
		// outputDir or outputMap
		if cli.OutputMap != "" {
			// for each input, render outputMap template to get output path
			// need to create a template for outputMap that uses ctx: .in and .ctx
			mapTmpl := template.New("outputMap").Delims(cli.LeftDelim, cli.RightDelim)
			// missingKey?
			switch cli.MissingKey{
			case "error":
				mapTmpl=mapTmpl.Option("missingkey=error")
			case "zero":
				mapTmpl=mapTmpl.Option("missingkey=zero")
			default:
				mapTmpl=mapTmpl.Option("missingkey=invalid")
			}
			// need funcMap for outputMap too? It should have same funcs as main
			// create rootData for funcMap? Use same rootData as earlier? But we don't have rootData here global? We'll reconstruct minimal
			// For simplicity, build funcMap with empty rootData? Actually outputMap needs access to datasources etc
			// We'll attempt to handle later in main where we have rootData
			// This function currently doesn't have access to rootData, so we need to pass it
			return fmt.Errorf("outputMap handling requires rootData")
		}
		// outputDir case: write each file to outputDir preserving relative path
		for i, out := range outputs {
			inPath := outNames[i]
			rel, _:=filepath.Rel(cli.InputDir, inPath)
			outPath:=filepath.Join(cli.OutputDir, rel)
			// ensure dir exists with same permissions as inputDir? Simplified: MkdirAll 0755
			if strings.TrimSpace(out)==""{
				logDebug("skipping empty output", fmt.Sprintf("file=%s", outPath))
				continue
			}
			dir:=filepath.Dir(outPath)
			if err:=os.MkdirAll(dir, 0755); err!=nil{return err}
			// determine mode
			mode:=os.FileMode(0644)
			if chmodSet{
				mode=chmodMode
			} else {
				if fi, err:=os.Stat(inPath); err==nil{
					mode=fi.Mode()
				}
			}
			if err:=os.WriteFile(outPath, []byte(out), mode); err!=nil{return err}
			if chmodSet{
				os.Chmod(outPath, mode)
			}
		}
		return nil
	}
	// non-inputDir cases
	if len(cli.OutputFiles)>0 {
		for i, out := range outputs {
			outPath:=cli.OutputFiles[i]
			if strings.TrimSpace(out)==""{
				// skip writing empty
				// if output is "-" (stdout), still skip? Original skips writing output -> not print
				// For stdout case, we should not write
				continue
			}
			if outPath=="-"{
				fmt.Fprint(os.Stdout, out)
			} else {
				dir:=filepath.Dir(outPath)
				os.MkdirAll(dir, 0755)
				mode:=os.FileMode(0644)
				if chmodSet{
					mode=chmodMode
				} else if len(outNames[i])>0 && outNames[i]!="<arg>" && outNames[i]!="-" {
					if fi,err:=os.Stat(outNames[i]); err==nil{ mode=fi.Mode()}
				}
				if err:=os.WriteFile(outPath, []byte(out), mode); err!=nil{return err}
				if chmodSet{
					os.Chmod(outPath, mode)
				}
			}
		}
		return nil
	}
	// default stdout
	for _, out := range outputs {
		if strings.TrimSpace(out)==""{
			continue
		}
		fmt.Fprint(os.Stdout, out)
	}
	return nil
}

