var plugins = map[string]PluginInfo{}

func loadPlugins() error {
	// parse --plugin flags: name=path
	for _, p := range cli.Plugins {
		parts:=strings.SplitN(p,"=",2)
		if len(parts)!=2{continue}
		name, cmd:=parts[0], parts[1]
		plugins[name]=PluginInfo{Cmd:cmd, Timeout: 5*time.Second}
	}
	// plugin timeout from env?
	if v:=os.Getenv("GOMPLATE_PLUGIN_TIMEOUT"); v!=""{
		if d,err:=time.ParseDuration(v); err==nil{
			for k,pl:=range plugins{ pl.Timeout=d; plugins[k]=pl}
		}
	}
	// TODO: config plugins with pipe etc not handled
	return nil
}

func pluginFunc(name string) func(...interface{}) (string, error){
	info, ok:=plugins[name]
	if !ok{
		return func(args ...interface{}) (string, error){ return "", fmt.Errorf("plugin %s not found", name)}
	}
	return func(args ...interface{}) (string, error){
		// args are passed as command args, last arg maybe piped?
		// If pipe true, last arg is stdin, rest are args
		// else all args are cmd args
		var cmdArgs []string
		cmdArgs = append(cmdArgs, info.Args...)
		var stdinStr string
		if info.Pipe && len(args)>0{
			// last arg is stdin
			last:=args[len(args)-1]
			stdinStr = toString(last)
			for _, a:=range args[:len(args)-1]{
				cmdArgs=append(cmdArgs, toString(a))
			}
		} else {
			for _, a:=range args{ cmdArgs=append(cmdArgs, toString(a))}
		}
		_ = stdinStr
		// For now just execute simple
		// Use timeout
		// Simplified: use combined? We'll just handle non-pipe case via exec
		return execPlugin(info.Cmd, cmdArgs, stdinStr, info.Timeout)
	}
}
