	pflag.StringSliceVar(&cli.Excludes, "exclude", nil, "glob of files to not parse")
	pflag.StringSliceVar(&cli.ExcludeProcessing, "exclude-processing", nil, "glob of files to be copied without parsing")
	pflag.StringSliceVar(&cli.Includes, "include", nil, "glob of files to parse")
	pflag.StringSliceVarP(&cli.OutputFiles, "out", "o", nil, "output file name. Omit to use standard output.")
	pflag.StringSliceVarP(&cli.Templates, "template", "t", nil, "Additional template file(s)")
	pflag.StringVar(&cli.OutputDir, "output-dir", ".", "directory to store the processed templates. Only used for --input-dir")
	pflag.StringVar(&cli.OutputMap, "output-map", "", "Template string to map the input file to an output path")
	pflag.StringVar(&cli.Chmod, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
	pflag.BoolVar(&cli.ExecPipe, "exec-pipe", false, "pipe the output to the post-run exec command")
	pflag.StringVar(&cli.LeftDelim, "left-delim", "{{", "override the default left-delimiter")
	pflag.StringVar(&cli.RightDelim, "right-delim", "}}", "override the default right-delimiter")
	pflag.StringVar(&cli.MissingKey, "missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")
	pflag.BoolVar(&cli.Experimental, "experimental", false, "enable experimental features")
	pflag.BoolVarP(&cli.Verbose, "verbose", "V", false, "output extra information about what gomplate is doing")
	pflag.StringVar(&cli.Config, "config", ".gomplate.yaml", "config file (overridden by commandline flags)")
	// help and version are handled via pflag automatically but we will manual
	pflag.BoolP("help", "h", false, "help for gomplate")
	pflag.BoolP("version", "v", false, "version for gomplate")

	// env defaults for left/right delim
	if v := os.Getenv("GOMPLATE_LEFT_DELIM"); v != "" {
		pflag.Lookup("left-delim").DefValue = v
		// if not set via flag, set default
		if !pflag.Lookup("left-delim").Changed {
			cli.LeftDelim = v
		}
	}
	if v := os.Getenv("GOMPLATE_RIGHT_DELIM"); v != "" {
		pflag.Lookup("right-delim").DefValue = v
		if !pflag.Lookup("right-delim").Changed {
			cli.RightDelim = v
		}
	}
	if v := os.Getenv("GOMPLATE_EXPERIMENTAL"); v != "" {
		if v == "true" || v == "1" {
			pflag.Lookup("experimental").DefValue = "true"
			if !pflag.Lookup("experimental").Changed {
				cli.Experimental = true
			}
		}
	}
	// config from env
	if v := os.Getenv("GOMPLATE_CONFIG"); v != "" {
		if !pflag.Lookup("config").Changed {
			cli.Config = v
		}
	}

	pflag.Parse()

	// check help/version
	if h, _ := pflag.CommandLine.GetBool("help"); h {
		printHelp()
		os.Exit(0)
	}
	if v, _ := pflag.CommandLine.GetBool("version"); v {
		fmt.Fprintf(os.Stdout, "gomplate version %s\n", version)
		os.Exit(0)
	}

	// detect if -i was set
	cli.InSet = pflag.Lookup("in").Changed
	if cli.InSet {
		// InSet true even if empty string?
	}

	// handle GOMPLATE_LEFT_DELIM/RIGHT_DELIM if flag not changed and env set
	if !pflag.Lookup("left-delim").Changed {
		if v := os.Getenv("GOMPLATE_LEFT_DELIM"); v != "" {
			cli.LeftDelim = v
		}
	}
	if !pflag.Lookup("right-delim").Changed {
		if v := os.Getenv("GOMPLATE_RIGHT_DELIM"); v != "" {
			cli.RightDelim = v
		}
	}
	if !pflag.Lookup("experimental").Changed {
		if v := os.Getenv("GOMPLATE_EXPERIMENTAL"); v != "" && (v=="true"||v=="1") {
			cli.Experimental = true
		}
	}
	// also GOMPLATE_PLUGIN_TIMEOUT env for later

	// postExec after --
	postExec = pflag.Args()
	// pflag.Args includes everything after --? In pflag, "--" stops parsing, args after are in pflag.Args()
	// But we need to distinguish: if user passes "gomplate -i hi -- cat file", pflag will treat "cat" as arg
	// That's postExec

	// init log format
	initLogFormat()
	if lf := os.Getenv("GOMPLATE_LOG_FORMAT"); lf != "" {
		logFormat = lf
	}
}

func loadConfigFile(path string) (*Config, error) {
	if path == "" {
		return &Config{}, nil
	}
	// if default and not exists, return empty without error
	if _, err := os.Stat(path); err != nil {
		if path == ".gomplate.yaml" && os.IsNotExist(err) {
			return &Config{}, nil
		}
		// if explicit and not exists, error? But original seems to ignore missing default only
		// For explicit path, if not exists, treat as error? Let's not error if file not exists but allow?
		// The error when config missing? Not observed. We'll return empty.
		return &Config{}, nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		// mimic error: parsing config file "...": YAML decoding failed, syntax may be invalid: yaml: ...
		return nil, fmt.Errorf("parsing config file %q: YAML decoding failed, syntax may be invalid: %v", path, err)
	}
	return &cfg, nil
}

func mergeConfig(cfg *Config) error {
	// need to track which flags were changed via pflag
	// For string slice flags, we need to know if changed: if not changed but config has value, use config
	// For strings, similarly.

	// Datasources
	if !pflag.Lookup("datasource").Changed && cfg.Datasources != nil {
		for alias, ds := range cfg.Datasources {
			// ds.URL
			entry := alias + "=" + ds.URL
			cli.Datasources = append(cli.Datasources, entry)
			// headers: store as datasource-header entries? For now stash headers separately? The datasource-header flag is for http headers.
			// We need to preserve headers per datasource. We'll keep a global header map.
			for k, vals := range ds.Header {
				for _, v := range vals {
					cli.DatasourceHeaders = append(cli.DatasourceHeaders, fmt.Sprintf("%s=%s: %s", alias, k, v))
				}
			}
		}
	}
	if !pflag.Lookup("context").Changed && cfg.Context != nil {
		for alias, ds := range cfg.Context {
			entry := alias + "=" + ds.URL
			cli.Contexts = append(cli.Contexts, entry)
		}
	}
	if !pflag.Lookup("template").Changed && cfg.Templates != nil {
		for alias, ds := range cfg.Templates {
			entry := alias + "=" + ds.URL
			cli.Templates = append(cli.Templates, entry)
		}
	}
	if !pflag.Lookup("plugin").Changed && cfg.Plugins != nil {
		for name, val := range cfg.Plugins {
			switch v := val.(type) {
			case string:
				cli.Plugins = append(cli.Plugins, name+"="+v)
			case map[string]interface{}:
				// cmd field
				cmd := ""
				if c, ok := v["cmd"]; ok {
					cmd = fmt.Sprintf("%v", c)
				}
				cli.Plugins = append(cli.Plugins, name+"="+cmd)
				// TODO: handle pipe, args, timeout? For now ignore
			}
		}
	}
	if !pflag.Lookup("file").Changed && len(cfg.InputFiles) > 0 {
		cli.InputFiles = append(cli.InputFiles, cfg.InputFiles...)
	}
	if !pflag.Lookup("in").Changed && cfg.In != nil {
		cli.In = *cfg.In
		cli.InSet = true
	}
	if !pflag.Lookup("input-dir").Changed && cfg.InputDir != nil {
		cli.InputDir = *cfg.InputDir
	}
	if !pflag.Lookup("exclude").Changed && len(cfg.Excludes) > 0 {
		cli.Excludes = append(cli.Excludes, cfg.Excludes...)
	}
	if !pflag.Lookup("exclude-processing").Changed && len(cfg.ExcludeProcessing) > 0 {
		cli.ExcludeProcessing = append(cli.ExcludeProcessing, cfg.ExcludeProcessing...)
	}
	// include: config uses excludes with ! prefix? But we handle simple
	if !pflag.Lookup("out").Changed && len(cfg.OutputFiles) > 0 {
		cli.OutputFiles = append(cli.OutputFiles, cfg.OutputFiles...)
	}
	if !pflag.Lookup("output-dir").Changed && cfg.OutputDir != nil {
		cli.OutputDir = *cfg.OutputDir
		pflag.Lookup("output-dir").DefValue = *cfg.OutputDir
	}
	if !pflag.Lookup("output-map").Changed && cfg.OutputMap != nil {
		cli.OutputMap = *cfg.OutputMap
	}
	if !pflag.Lookup("chmod").Changed && cfg.Chmod != nil {
		cli.Chmod = *cfg.Chmod
	}
	if !pflag.Lookup("exec-pipe").Changed && cfg.ExecPipe != nil {
		cli.ExecPipe = *cfg.ExecPipe
	}
	if !pflag.Lookup("left-delim").Changed && cfg.LeftDelim != nil {
		cli.LeftDelim = *cfg.LeftDelim
	}
	if !pflag.Lookup("right-delim").Changed && cfg.RightDelim != nil {
		cli.RightDelim = *cfg.RightDelim
	}
	if !pflag.Lookup("missing-key").Changed && cfg.MissingKey != nil {
		cli.MissingKey = *cfg.MissingKey
	}
	if !pflag.Lookup("experimental").Changed && cfg.Experimental != nil {
		cli.Experimental = *cfg.Experimental
	}
	// pluginTimeout not flagged directly, but we can handle later

	// env overrides if flag not changed and config not set?
	// left/right already handled, experimental already.
	return nil
}

func validateConfig() error {
	// count exclusive sources: in, inputFiles, inputDir
	inCount := 0
	if cli.InSet {
		inCount++
	}
	if len(cli.InputFiles) > 0 {
		inCount++
	}
	if cli.InputDir != "" {
		inCount++
	}
	if inCount > 1 {
		// determine which two are set
		var opts []string
		if cli.InSet {
			opts = append(opts, "'in'")
		}
		if len(cli.InputFiles)>0 {
			opts = append(opts, "'inputFiles'")
		}
		if cli.InputDir!="" {
			opts = append(opts, "'inputDir'")
		}
		// produce error with yaml dump of config
		// Need to produce config yaml for error
		// Replicate exact message: failed to validate config: only one of these options is supported at a time: 'in', 'inputDir' etc
		msg := fmt.Sprintf("only one of these options is supported at a time: %s", strings.Join(opts, ", "))
		return fmt.Errorf("failed to validate config: %s\n---\n%s", msg, dumpConfigForError())
	}
	// output exclusivity: outputDir vs outputMap vs outputFiles?
	// Docs: outputDir vs outputFiles vs outputMap exclusivity
	// From tests: inputDir with outputDir and outputMap error: only one of 'outputDir', 'outputMap'
	// Also inputDir requires outputDir or outputMap
	// And outputFiles vs outputDir vs outputMap also exclusivity?
	// Let's handle: if cli.OutputDir != "" && cli.OutputMap != ""
	// But need to check when they are set via default? outputDir default is "." even when not set? In original, outputDir default "." but only validated when inputDir set? In help default "." but validation only when inputDir set?
	// In observed error: when we did --input-dir without outputDir, error was parse template for binary? Actually test with --input-dir /tmp without outputDir gave weird error but earlier with default it worked when we used --input-dir /tmp/ind --output-dir /tmp/outd (explicit). When we tried --input-dir alone it tried to use "." as outputDir and gave not error about missing outputDir. So outputDir default is ok.
	// So validation: if cli.InputDir != "" and cli.OutputMap != "" and cli.OutputDir != "."? But default "." counts as set?
	// Original says inputDir must be used with outputDir or outputMap, but they are defaults? Let's see help: --output-dir default "." . So if inputDir set without outputDir, it still has default "." so passes. Our earlier test with --input-dir /tmp/ind --output-map out/{{.in}} plus --output-dir default gave error only when we explicitly also set outputDir via our test? We did: --input-dir /tmp/ind --output-map X --output-dir /tmp/out2 gave error about only one of outputDir/outputMap. So they conflict when both are non-empty explicit? But we set outputDir to default "." always, so if we set outputMap and outputDir default ".", it would conflict always, but test with only outputMap showed rc 0 and output was created in out/... So they didn't treat default "." as conflicting when outputMap is set. So we need to know if outputDir was explicitly set vs default.
	// Use pflag Changed to detect.
	if cli.OutputMap != "" && pflag.Lookup("output-dir").Changed {
		// if outputMap set and outputDir explicitly set (changed from default) then conflict
		return fmt.Errorf("failed to validate config: only one of these options is supported at a time: 'outputDir', 'outputMap'\n---\n%s", dumpConfigForError())
	}
	// Also check if cli.InputDir != "" and neither outputDir changed nor outputMap set? But outputDir default "." satisfies, so no error.

	// check outputFiles vs outputDir/outputMap/inputDir combos
	if len(cli.OutputFiles) > 0 {
		if cli.InputDir != "" {
			return fmt.Errorf("failed to validate config: only one of these options is supported at a time: 'outputFiles', 'inputDir'\n---\n%s", dumpConfigForError())
		}
		if cli.OutputMap != "" {
			return fmt.Errorf("failed to validate config: only one of these options is supported at a time: 'outputFiles', 'outputMap'\n---\n%s", dumpConfigForError())
		}
		// also if outputDir explicitly set and not default? But we saw help: outputDir only used for inputDir. So if outputFiles set and outputDir changed (not default ".")? Might be error about outputDir vs outputFiles.
		if pflag.Lookup("output-dir").Changed && cli.OutputDir != "." {
			return fmt.Errorf("failed to validate config: only one of these options is supported at a time: 'outputFiles', 'outputDir'\n---\n%s", dumpConfigForError())
		}
	}
	// check counts
	if len(cli.OutputFiles) > 0 {
		// need to match input count
		inCountFiles := 0
		if cli.InSet {
			inCountFiles = 1
		} else if len(cli.InputFiles) > 0 {
			inCountFiles = len(cli.InputFiles)
		} else {
			// default stdin as one input
			inCountFiles = 1
		}
		if len(cli.OutputFiles) != inCountFiles {
			return fmt.Errorf("failed to validate config: must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options\n---\n%s", len(cli.OutputFiles), inCountFiles, dumpConfigForError())
		}
	}
	// missing-key validation
	validMissing := map[string]bool{"error":true, "zero":true, "default":true, "invalid":true, "":true}
	if !validMissing[cli.MissingKey] {
		return fmt.Errorf("failed to validate config: not allowed value for the 'missing-key' flag: %s. Allowed values: ,error,zero,default,invalid\n---\n%s", cli.MissingKey, dumpConfigForError())
	}
	// chmod validation
	if cli.Chmod != "" {
		if _, err := strconv.ParseUint(cli.Chmod, 8, 32); err != nil {
			// error is shown as failed to gather? In test chmod invalid gave "failed to gather templates... strconv.ParseUint: parsing \"0invalid\": invalid syntax"
			// But also config validation might produce same. We'll return gather error later.
			// For now, let validation pass and let gather fail? Let's replicate gather error: We'll return error with that message wrapped as failed to gather...
			return fmt.Errorf("strconv.ParseUint: parsing \"0%s\": invalid syntax", cli.Chmod)
		}
	}
	return nil
}

func dumpConfigForError() string {
	// produce yaml like original: shows in, inputFiles, outputFiles, inputDir, outputDir, outputMap, leftDelim, rightDelim, missingKey, pluginTimeout
	// Let's produce minimal similar to observed: each line key: value
	var lines []string
	if cli.InSet {
		lines = append(lines, fmt.Sprintf("in: %s", yamlQuote(cli.In)))
	}
	if len(cli.InputFiles)>0 {
		lines = append(lines, fmt.Sprintf("inputFiles: [%s]", strings.Join(cli.InputFiles, ", ")))
	}
	if len(cli.OutputFiles)>0 {
		// outputFiles: ['-'] etc
		quoted := []string{}
		for _, f := range cli.OutputFiles {
			quoted = append(quoted, fmt.Sprintf("'%s'", f))
		}
		lines = append(lines, fmt.Sprintf("outputFiles: [%s]", strings.Join(quoted, ", ")))
	}
	if cli.InputDir != "" {
		lines = append(lines, fmt.Sprintf("inputDir: %s", cli.InputDir))
	}
	if cli.OutputDir != "" {
		lines = append(lines, fmt.Sprintf("outputDir: %s", cli.OutputDir))
	}
	if cli.OutputMap != "" {
		lines = append(lines, fmt.Sprintf("outputMap: %s", cli.OutputMap))
	}
	lines = append(lines, fmt.Sprintf("leftDelim: '%s'", cli.LeftDelim))
	lines = append(lines, fmt.Sprintf("rightDelim: '%s'", cli.RightDelim))
	lines = append(lines, fmt.Sprintf("missingKey: %s", cli.MissingKey))
	// pluginTimeout default 5s
	pt := "5s"
	if v := os.Getenv("GOMPLATE_PLUGIN_TIMEOUT"); v != "" {
		pt = v
	}
	lines = append(lines, fmt.Sprintf("pluginTimeout: %s", pt))
	return strings.Join(lines, "\n")
}
func yamlQuote(s string) string {
	if strings.Contains(s, "\n") {
		return fmt.Sprintf("'%s'", strings.ReplaceAll(s, "'", "''"))
	}
	if s=="" {
		return "''"
	}
	// simple quote if needed
	if strings.Contains(s, "'") || strings.Contains(s, ":") {
		return fmt.Sprintf("'%s'", s)
	}
	return s
}

// datasource handling
type DataSource struct {
	Alias string
	URL   string
	Data  interface{}
	Header map[string][]string
}

var datasources = map[string]*DataSource{}
var datasourceHeaders = map[string]map[string][]string{}

func parseDatasourceHeaders() {
	for _, h := range cli.DatasourceHeaders {
		// format alias=Name: value
		parts := strings.SplitN(h, "=", 2)
		if len(parts)!=2 { continue }
		alias := parts[0]
		rest := parts[1]
		// rest is "Name: value"
		hParts := strings.SplitN(rest, ":", 2)
		if len(hParts)!=2 { continue }
		name := strings.TrimSpace(hParts[0])
		val := strings.TrimSpace(hParts[1])
		if _, ok := datasourceHeaders[alias]; !ok {
			datasourceHeaders[alias]=map[string][]string{}
		}
		datasourceHeaders[alias][name] = append(datasourceHeaders[alias][name], val)
	}
}

func loadDatasources() error {
	for _, d := range cli.Datasources {
		parts := strings.SplitN(d, "=", 2)
		if len(parts)!=2 {
			return fmt.Errorf("invalid datasource %q", d)
		}
		alias, u := parts[0], parts[1]
		ds := &DataSource{Alias: alias, URL: u}
		// headers
		if hdr, ok := datasourceHeaders[alias]; ok {
			ds.Header = hdr
		}
		// load data
		data, err := readDatasourceURL(u)
		if err != nil {
			return fmt.Errorf("couldn't read datasource '%s' (%s): %v", alias, u, err)
		}
		ds.Data = data
		datasources[alias]=ds
	}
	for _, c := range cli.Contexts {
		parts := strings.SplitN(c, "=", 2)
		if len(parts)!=2 {
			return fmt.Errorf("invalid context %q", c)
		}
		alias, u := parts[0], parts[1]
		data, err := readDatasourceURL(u)
		if err != nil {
			return fmt.Errorf("couldn't read datasource '%s' (%s): %v", alias, u, err)
		}
		// store into context data later
		datasources["_ctx_"+alias]=&DataSource{Alias: alias, URL: u, Data: data}
	}
	return nil
}

func readDatasourceURL(u string) (interface{}, error) {
	// parse URL
	parsed, err := url.Parse(u)
	if err != nil {
		// fallback to plain file path
		parsed = &url.URL{Scheme: "", Path: u}
	}
	scheme := parsed.Scheme
	// handle env, file, stdin, http, https, etc
	// also support plain path without scheme as file
	if scheme == "" {
		// treat as file path relative
		return readFileDatasource(u, "")
	}
	switch scheme {
	case "file":
		path := parsed.Path
		// for file:// with host?
		if parsed.Host != "" {
			path = parsed.Host + path
		}
		// handle query type
		mime := parsed.Query().Get("type")
		return readFileDatasource(path, mime)
	case "env":
		// env:///VAR?type=...
		varName := strings.TrimPrefix(parsed.Path, "/")
		if varName == "" {
			varName = parsed.Host
		}
		val := os.Getenv(varName)
		if val == "" {
			// try _FILE fallback?
			if fval := os.Getenv(varName + "_FILE"); fval != "" {
				if data, err := os.ReadFile(fval); err == nil {
					val = string(data)
				}
			}
		}
		mime := parsed.Query().Get("type")
		if mime == "" && parsed.Host != "" {
			//? maybe type in query already
		}
		// if type is json/yaml etc, parse
		return parseContent(val, mime, varName)
	case "stdin":
		// stdin:///in.json?type=...
		// read from stdin? But stdin may be used for template. We'll read from os.Stdin
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, err
		}
		mime := parsed.Query().Get("type")
		return parseContent(string(data), mime, "")
	case "http", "https":
		// fetch via http
		mime := parsed.Query().Get("type")
		req, err := http.NewRequest("GET", u, nil)
		if err != nil {
			return nil, err
		}
		// add headers if any? For simplicity ignore alias headers? We'll attempt
		// Need alias to find headers: but we don't know alias here
		// So handle headers via global datasourceHeaders map lookup by alias? Not available here
		client := &http.Client{Timeout: 10*time.Second}
		resp, err := client.Do(req)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		body, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, err
		}
		return parseContent(string(body), mime, "")
	default:
		// treat as file path with scheme as part of path? Could be like "./file"
		return readFileDatasource(u, "")
	}
}

func readFileDatasource(path, mime string) (interface{}, error) {
	if path == "" {
		return nil, fmt.Errorf("empty path")
	}
	// handle url encoding? path may be /tmp/file.json
	// For file DS, if path is relative without scheme, it's already passed as u
	dataBytes, err := os.ReadFile(path)
	if err != nil {
		// try to provide error similar to original: open (url: "file:///", name: "/no/such/file"): open no/such/file: no such file or directory
		// We'll just return err with wrapper
		return nil, fmt.Errorf("open (url: \"file:///\", name: \"%s\"): open %s: %v", path, strings.TrimPrefix(path,"/"), err)
	}
	content := string(dataBytes)
	if mime == "" {
		// infer from extension
		ext := strings.ToLower(filepath.Ext(path))
		switch ext {
		case ".json":
			mime = "application/json"
		case ".yaml", ".yml":
			mime = "application/yaml"
		case ".toml":
			mime = "application/toml"
		case ".csv":
			mime = "text/csv"
		case ".xml":
			mime = "text/xml"
		default:
			// try to detect json?
			mime = ""
		}
	}
	return parseContent(content, mime, path)
}

func parseContent(content, mime, path string) (interface{}, error) {
	if mime != "" {
		switch {
		case strings.Contains(mime, "json"):
			var v interface{}
			if err := json.Unmarshal([]byte(content), &v); err != nil {
				return nil, err
			}
			return v, nil
		case strings.Contains(mime, "yaml"):
			var v interface{}
			if err := yaml.Unmarshal([]byte(content), &v); err != nil {
				return nil, err
			}
			// yaml.v3 unmarshals to map[interface{}]interface{}? Actually gopkg.in/yaml.v3 does map[interface{}] but we use same? The go.yaml.in does map[string]interface{} but we use gopkg.in which may produce map[interface{}]? For simplicity, convert to JSON roundtrip to normalize
			// Convert via json marshal/unmarshal to get map[string]interface{}
			// But we can also handle manually: if v is map[interface{}]...
			// Quick normalize: marshal to json then unmarshal
			if m, ok := v.(map[string]interface{}); ok {
				return m, nil
			}
			// try to convert via yaml to json
			jb, err := json.Marshal(v)
			if err == nil {
				var out interface{}
				json.Unmarshal(jb, &out)
				return out, nil
			}
			return v, nil
		case strings.Contains(mime, "toml"):
			var v interface{}
			if err := toml.Unmarshal([]byte(content), &v); err != nil {
				return nil, err
			}
			return v, nil
		case strings.Contains(mime, "csv"):
			r := csv.NewReader(strings.NewReader(content))
			records, err := r.ReadAll()
			if err != nil {
				return nil, err
			}
			return records, nil
		}
	}
	// auto-detect: try json, then yaml, then toml, then return string
	// Try json
	var jv interface{}
	if err := json.Unmarshal([]byte(content), &jv); err == nil {
		// if json is object or array, return it, else maybe string? For json we return whatever
		// But for plain string datasource like env var containing json array, should parse?
		return jv, nil
	}
	// Try yaml
	var yv interface{}
	if err := yaml.Unmarshal([]byte(content), &yv); err == nil {
		// if yaml parses to map or slice, return
		// For env var with yaml content, this works
		// But we need to normalize map keys
		if yv != nil {
			// normalize
			jb, _ := json.Marshal(yv)
			var out interface{}
			json.Unmarshal(jb, &out)
			if out != nil {
				return out, nil
			}
			return yv, nil
		}
	}
	// Try toml
	var tv interface{}
	if err := toml.Unmarshal([]byte(content), &tv); err == nil {
		// check if tv is not empty map?
		if m, ok := tv.(map[string]interface{}); ok && len(m)>0 {
			return tv, nil
		}
	}
	// fallback: return string
	return content, nil
}

