func (c *CollFuncs) Has(in interface{}, item interface{}) bool {
	switch v := in.(type) {
	case []interface{}:
		for _, e := range v {
			if fmt.Sprintf("%v", e)==fmt.Sprintf("%v", item) { return true }
		}
		return false
	case map[string]interface{}:
		_, ok := v[toString(item)]
		return ok
	default:
		// try reflection?
		return false
	}
}
func (c *CollFuncs) Append(item interface{}, list interface{}) ([]interface{}, error) {
	switch v := list.(type) {
	case []interface{}:
		return append(v, item), nil
	default:
		return nil, fmt.Errorf("expected an array")
	}
}
func (c *CollFuncs) Prepend(item interface{}, list interface{}) ([]interface{}, error) {
	switch v := list.(type) {
	case []interface{}:
		return append([]interface{}{item}, v...), nil
	default:
		return nil, fmt.Errorf("expected an array")
	}
}
func (c *CollFuncs) Uniq(in interface{}) ([]interface{}, error) {
	switch v := in.(type) {
	case []interface{}:
		seen := map[string]bool{}
		var out []interface{}
		for _, e := range v {
			k := fmt.Sprintf("%v", e)
			if !seen[k] {
				seen[k]=true
				out=append(out,e)
			}
		}
		return out, nil
	default:
		return nil, fmt.Errorf("expected an array")
	}
}
func (c *CollFuncs) Reverse(in interface{}) ([]interface{}, error) {
	switch v := in.(type) {
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, e := range v {
			out[len(v)-1-i]=e
		}
		return out, nil
	default:
		return nil, fmt.Errorf("expected an array")
	}
}
func (c *CollFuncs) Sort(dir interface{}, in interface{}) ([]interface{}, error) {
	// simplified: dir is "asc" or "desc"
	d := toString(dir)
	var list []interface{}
	switch v := in.(type) {
	case []interface{}:
		list = append([]interface{}{}, v...)
	default:
		return nil, fmt.Errorf("expected an array")
	}
	sort.Slice(list, func(i,j int) bool {
		si := fmt.Sprintf("%v", list[i])
		sj := fmt.Sprintf("%v", list[j])
		if d=="desc" {
			return si > sj
		}
		return si < sj
	})
	return list, nil
}
