type ConvFuncs struct{}
func (c *ConvFuncs) Bool(in string) bool {
	s := strings.ToLower(strings.TrimSpace(in))
	return s=="true"||s=="1"||s=="yes"||s=="on"
}
func (c *ConvFuncs) Default(def, in interface{}) interface{} {
	if in==nil { return def }
	switch v:=in.(type){
	case string:
		if v=="" { return def }
		return v
	case []interface{}:
		if len(v)==0 { return def }
		return v
	case map[string]interface{}:
		if len(v)==0 { return def }
		return v
	case bool:
		if !v { return def }
		return v
	case int, int64, float64:
		if fmt.Sprintf("%v",v)=="0" || fmt.Sprintf("%v",v)=="0.0" { return def }
		return v
	default:
		if fmt.Sprintf("%v",v)=="" || fmt.Sprintf("%v",v)=="<no value>" { return def }
		return v
	}
}
func (c *ConvFuncs) Join(in interface{}, sep string) (string, error) {
	switch v:=in.(type){
	case []interface{}:
		strs:=make([]string,len(v))
		for i,e:=range v{ strs[i]=toString(e)}
		return strings.Join(strs, sep), nil
	case []string:
		return strings.Join(v, sep), nil
	default:
		return "", fmt.Errorf("input to Join must be an array")
	}
}
