type MathFuncs struct{}
func (m *MathFuncs) Add(vals ...interface{}) (interface{}, error) {
	if len(vals)==0{return 0,nil}
	hasFloat:=false
	for _,v:=range vals{
		if _, ok:=v.(float64); ok { hasFloat=true}
		if s, ok:=v.(string); ok && (strings.Contains(s,".")||strings.Contains(s,"e")) { hasFloat=true}
	}
	if hasFloat{
		sum:=0.0
		for _,v:=range vals{ f,err:=toFloat64(v); if err!=nil{return nil,err}; sum+=f}
		return sum,nil
	}
	sum:=int64(0)
	for _,v:=range vals{ n,err:=toInt64(v); if err!=nil{return nil,err}; sum+=n}
	return sum,nil
}
func (m *MathFuncs) Sub(a,b interface{}) (interface{}, error) {
	af,err:=toFloat64(a); if err!=nil{return nil,err}
	bf,err:=toFloat64(b); if err!=nil{return nil,err}
	// if both int-like, return int?
	ai,_:=toInt64(a); bi,_:=toInt64(b)
	if float64(ai)==af && float64(bi)==bf {
		return ai - bi, nil
	}
	return af - bf, nil
}
func (m *MathFuncs) Mul(vals ...interface{}) (interface{}, error) {
	if len(vals)==0{return 1,nil}
	hasFloat:=false
	for _,v:=range vals{
		if _, ok:=v.(float64); ok { hasFloat=true}
	}
	if hasFloat{
		prod:=1.0
		for _,v:=range vals{ f,_:=toFloat64(v); prod*=f}
		return prod,nil
	}
	prod:=int64(1)
	for _,v:=range vals{ n,_:=toInt64(v); prod*=n}
	return prod,nil
}
func (m *MathFuncs) Div(a,b interface{}) (interface{}, error) {
	af,_:=toFloat64(a); bf,_:=toFloat64(b)
	if bf==0{return nil,fmt.Errorf("division by zero")}
	return af/bf,nil
}
func (m *MathFuncs) Rem(a,b interface{}) (interface{}, error) {
	ai,_:=toInt64(a); bi,_:=toInt64(b)
	if bi==0{return nil,fmt.Errorf("division by zero")}
	return ai%bi,nil
}
func (m *MathFuncs) Pow(a,b interface{}) (interface{}, error) {
	af,_:=toFloat64(a); bf,_:=toFloat64(b)
	return math.Pow(af,bf),nil
}
func (m *MathFuncs) Abs(in interface{}) (interface{}, error) {
	f,_:=toFloat64(in)
	if f<0{ f=-f}
	// if original int, return int?
	if i,err:=toInt64(in); err==nil && float64(i)==f || float64(-i)==f {
		if i<0{ return -i,nil}
		return i,nil
	}
	return f,nil
}
func (m *MathFuncs) Ceil(in interface{}) (float64, error) { f,_:=toFloat64(in); return math.Ceil(f),nil}
func (m *MathFuncs) Floor(in interface{}) (float64, error){ f,_:=toFloat64(in); return math.Floor(f),nil}
func (m *MathFuncs) Round(in interface{}) (float64, error){ f,_:=toFloat64(in); return math.Round(f),nil}
func (m *MathFuncs) Max(vals ...interface{}) (interface{}, error){
	if len(vals)==0{return nil,fmt.Errorf("need args")}
	max, _:=toFloat64(vals[0])
	for _,v:=range vals[1:]{
		f,_:=toFloat64(v)
		if f>max{max=f}
	}
	// return int if all ints?
	return max,nil
}
func (m *MathFuncs) Min(vals ...interface{}) (interface{}, error){
	if len(vals)==0{return nil,fmt.Errorf("need args")}
	min, _:=toFloat64(vals[0])
	for _,v:=range vals[1:]{
		f,_:=toFloat64(v)
		if f<min{min=f}
	}
	return min,nil
}
func (m *MathFuncs) Seq(args ...interface{}) ([]int64, error){
	// seq can be 1 arg (end) -> 1..end
	// 2 args start end
	// 3 args start end step
	var start,end,step int64 =1,0,1
	switch len(args){
	case 1:
		end,_=toInt64(args[0])
	case 2:
		start,_=toInt64(args[0]); end,_=toInt64(args[1])
	case 3:
		start,_=toInt64(args[0]); end,_=toInt64(args[1]); step,_=toInt64(args[2])
	default:
		return nil,fmt.Errorf("wrong number of args for Seq: want 1 to 3 got %d", len(args))
	}
	// replicate math.Seq behavior
	if step==0{
		return []int64{},nil
	}
	if end < start && step >0 { step = -step }
	if end > start && step <0 { step = -step }
	end -= (end - start) % step
	seq := []int64{start}
	last := start
	for last != end {
		last = seq[len(seq)-1]+step
		seq = append(seq, last)
	}
	return seq,nil
}
func (m *MathFuncs) IsFloat(in interface{}) bool {
	s:=toString(in)
	_, err:=strconv.ParseFloat(s,64)
	// but need to check if contains decimal or exponent? original logic checks if parse succeeds and string contains "."? We'll just check parse and contains "." or "e"
	if err!=nil{return false}
	// check if string representation contains "."?
	// For int-like 1, IsFloat should be false? According spec: if decimal point part of input number, considered float even if decimal is 0.
	// Hard to replicate precisely, but approximate:
	if strings.Contains(s,".")||strings.Contains(strings.ToLower(s),"e")||strings.Contains(strings.ToLower(s),"nan")||strings.Contains(strings.ToLower(s),"inf"){
		return true
	}
	// if input is float type
	switch in.(type){
	case float32,float64:
		return true
	}
	return false
}
func (m *MathFuncs) IsInt(in interface{}) bool {
	s:=toString(in)
	_, err:=strconv.ParseInt(s,0,64)
	return err==nil && !m.IsFloat(in)
}
func (m *MathFuncs) IsNum(in interface{}) bool {
	s:=toString(in)
	_, err:=strconv.ParseFloat(s,64)
	if err==nil{return true}
	// also hex?
	_, err=strconv.ParseInt(s,0,64)
	return err==nil
}

