				// we need to exec
				// Use helper to run command
				if err:=runPostExec(cmdName, cmdArgs, combined); err!=nil{
					logError("", err.Error())
					os.Exit(1)
				}
			}
		} else {
			// regular write
			// For writeOutputs we need to handle chmod etc, but we already did for inputDir case inside writeOutputs
			// For now call helper that handles non-outputMap
			if err:=writeOutputsSimple(outputs, outNames, cli.Chmod); err!=nil{
				logError("", fmt.Sprintf("failed to gather templates for rendering: %v", err))
				os.Exit(1)
			}
			// postExec without pipe: run command after writing
			if len(postExec)>0{
				if err:=runPostExec(postExec[0], postExec[1:], ""); err!=nil{
					logError("", err.Error())
					os.Exit(1)
				}
			}
		}
	}

	if cli.Verbose {
		// completed
		switch logFormat{
		case "json":
			fmt.Fprintf(os.Stderr, "{\"time\":\"%s\",\"level\":\"DEBUG\",\"msg\":\"completed rendering\",\"templatesRendered\":%d,\"errors\":0,\"duration\":%d}\n", logTime(), len(inputs), 10000)
		case "console":
			fmt.Fprintf(os.Stderr, "%s DBG completed rendering templatesRendered=%d errors=0 duration=%dus\n", time.Now().Format("15:04:05"), len(inputs), 10000)
		default:
			logDebug("completed rendering", fmt.Sprintf("templatesRendered=%d",len(inputs)), "errors=0")
		}
	}
}

func writeOutputsSimple(outputs []string, outNames []string, chmodStr string) error{
	var chmodMode os.FileMode
	chmodSet:=false
	if chmodStr != ""{
		v,err:=strconv.ParseUint(chmodStr,8,32)
		if err!=nil{ return err}
		chmodMode=os.FileMode(v)
		chmodSet=true
	}
	if cli.InputDir != ""{
		for i,out:=range outputs{
			inPath:=outNames[i]
			rel,_:=filepath.Rel(cli.InputDir, inPath)
			outPath:=filepath.Join(cli.OutputDir, rel)
			if strings.TrimSpace(out)==""{continue}
			dir:=filepath.Dir(outPath)
			os.MkdirAll(dir,0755)
			mode:=os.FileMode(0644)
			if chmodSet{ mode=chmodMode} else { if fi,err:=os.Stat(inPath); err==nil{mode=fi.Mode()}}
			os.WriteFile(outPath, []byte(out), mode)
			if chmodSet{ os.Chmod(outPath, mode)}
		}
		return nil
	}
	if len(cli.OutputFiles)>0{
		for i,out:=range outputs{
			outPath:=cli.OutputFiles[i]
			if strings.TrimSpace(out)==""{continue}
			if outPath=="-"{
				fmt.Fprint(os.Stdout,out)
			} else {
				dir:=filepath.Dir(outPath)
				os.MkdirAll(dir,0755)
				mode:=os.FileMode(0644)
				if chmodSet{mode=chmodMode}else if len(outNames[i])>0 && outNames[i]!="<arg>" && outNames[i]!="-"{
					if fi,err:=os.Stat(outNames[i]); err==nil{mode=fi.Mode()}
				}
				os.WriteFile(outPath, []byte(out), mode)
				if chmodSet{os.Chmod(outPath,mode)}
			}
		}
		return nil
	}
	for _,out:=range outputs{
		if strings.TrimSpace(out)==""{continue}
		fmt.Fprint(os.Stdout,out)
	}
	return nil
}

