# In earlier error dumps, they had outputFiles: ['-'] with quotes, but for /tmp/a they had [/tmp/a] without quotes? Let's check.
# In earlier test with -i hi -f /tmp/a, orig dump was `inputFiles: [/tmp/a]` and `outputFiles: ['-']` -> inputFiles without quotes, outputFiles with quotes for '-'
# So they quote only when needed? Our code always quotes.

import pathlib
p=pathlib.Path("main.go")
txt=p.read_text()
# Fix both dump functions to not always quote, only when needed? Let's check inputFiles quoting: they show [/tmp/a] without quotes, but we do `strings.Join(cli.InputFiles, ", ")` without quotes also without quotes, so that's fine.
# But outputFiles we forced quotes: `'%s'` . Original for /tmp/empty_test shows without quotes, so we should not quote unless needed.

old1 = """\tif len(cli.OutputFiles)>0 {
\t\t\tquoted := []string{}
\t\t\tfor _, f := range cli.OutputFiles {
\t\t\t\tquoted = append(quoted, fmt.Sprintf("'%s'", f))
\t\t\t}
\t\t\tlines = append(lines, fmt.Sprintf("outputFiles: [%s]", strings.Join(quoted, ", ")))
\t\t} else {
\t\t\tlines = append(lines, "outputFiles: ['-']")
\t\t}"""
new1 = """\tif len(cli.OutputFiles)>0 {
\t\t\tlines = append(lines, fmt.Sprintf("outputFiles: [%s]", strings.Join(cli.OutputFiles, ", ")))
\t\t} else {
\t\t\tlines = append(lines, "outputFiles: ['-']")
\t\t}"""
# But this is in dumpConfigForError; need also fix verbose
if old1 in txt:
    # This old appears twice (error and verbose)
    txt=txt.replace(old1, new1)
    pathlib.Path("main.go").write_text(txt)
    print("fixed outputFiles quoting")
else:
    print("not found old1")
    # Check verbose version
    print("search")
    print(txt.find("outputFiles"))

# Also need to handle quoting for '-' case: original shows ['-'] with quotes, but simple join would give [-] without quotes for '-'.
# So for default case we need ['-'] with quotes, but for explicit /tmp/... we need without quotes?
# Maybe original quotes only when file is '-'? Let's check: In earlier verbose with outputFiles: ['/tmp/empty_test'] vs [/tmp/empty_test] conflict.
# So we need to handle: if file is "-", quote it, else not?

import re
txt=pathlib.Path("main.go").read_text()
old_verbose = """\tif len(cli.OutputFiles)>0 {
\t\t\tquoted := []string{}
\t\t\tfor _, f := range cli.OutputFiles {
\t\t\t\tquoted = append(quoted, fmt.Sprintf("'%s'", f))
\t\t\t}
\t\t\tlines = append(lines, fmt.Sprintf("outputFiles: [%s]", strings.Join(quoted, ", ")))
\t\t}"""
new_verbose = """\tif len(cli.OutputFiles)>0 {
\t\t\tparts := []string{}
\t\t\tfor _, f := range cli.OutputFiles {
\t\t\t\tif f == "-" {
\t\t\t\t\tparts = append(parts, "'-'")
\t\t\t\t} else {
\t\t\t\t\tparts = append(parts, f)
\t\t\t\t}
\t\t\t}
\t\t\tlines = append(lines, fmt.Sprintf("outputFiles: [%s]", strings.Join(parts, ", ")))
\t\t}"""
if old_verbose in txt:
    # Already replaced? Check
    print("found verbose old")
else:
    print("verbose old not found")
